SELECT * FROM leetcode_problem_tag 
WHERE problem_id = #{problemId}
ORDER BY tag_type, confidence DESC

SELECT DISTINCT problem_id FROM leetcode_problem_tag 
WHERE tag_type = #{tagType} AND tag_value = #{tagValue}
ORDER BY confidence DESC

SELECT DISTINCT problem_id FROM leetcode_problem_tag 
WHERE tag_type = #{tagType} 
AND tag_value IN

    #{tagValue}

ORDER BY confidence DESC

SELECT DISTINCT problem_id FROM leetcode_problem_tag WHERE tag_value IN
#{tagValue}
ORDER BY confidence DESC

SELECT DISTINCT tag_value FROM leetcode_problem_tag 
WHERE tag_type = #{tagType}
ORDER BY tag_value
